// Drives the REAL NearAdapter against REAL contracts (target/wasm) on a throwaway NEAR Sandbox: two market contracts that
// share the internal market id "mkt-1", one token, and the same local offer ids. Skipped when the sandbox binary or Wasm
// artifacts are missing. The "wallet" signs with keys generated by the harness; no testnet account or credential is used.
import { writeFileSync } from "node:fs";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import * as H from "./sandbox/harness.mjs";
import type { Market, Offer, TxState } from "@/lib/types";

const run = H.sandboxAvailable();
const g = vi.hoisted(() => ({ sbx: null as unknown, who: null as { accountId: string; keyPair: unknown } | null }));
vi.mock("@/lib/wallet", () => ({
  wallet: {
    account: () => g.who?.accountId ?? null,
    call: async (receiver: string, method: string, args: object, deposit: string, gas: string) => {
      const H2 = await import("./sandbox/harness.mjs");
      return H2.call(g.sbx, g.who, receiver, method, args, BigInt(deposit), BigInt(gas), method);
    },
  },
}));

const TG = 10n ** 12n;
const tok = (n: number) => BigInt(Math.round(n * 1e6));
const reporter = () => { const seen: TxState[] = []; return { r: (s: TxState) => seen.push(s), last: () => seen[seen.length - 1], seen }; };

describe.skipIf(!run)("Sandbox: two market contracts, one wallet", () => {
  let sbx: any, owner: any, alice: any, bob: any, tokenId: string;
  let A: Market, B: Market;
  let adapter: any;
  let calls = () => 0;
  const as = (k: any) => { g.who = k; };

  const mkMarket = async (ref: string, d: any, question: string): Promise<Market> => {
    const { toMarket } = await import("@/lib/api/map");
    const { apiMarket, FRESH } = await import("./helpers");
    void FRESH;
    const cfg = await H.view(sbx, d.contractId, "get_config");
    const meta = await H.view(sbx, tokenId, "ft_metadata");
    return toMarket(apiMarket(ref, { contractId: d.contractId, marketId: d.marketId, tokenId }, {
      question, trading: cfg.trading, token: { symbol: meta.symbol, name: meta.name, decimals: meta.decimals, isTestToken: true },
      tradingCutoff: { ns: d.cutoffNs, iso: null }, resolver: owner.accountId,
    }));
  };
  const acct = (who: any, m: Market) => adapter.getAccount(who.accountId, m);

  beforeAll(async () => {
    sbx = await H.startSandbox(); g.sbx = sbx;
    vi.stubEnv("NEXT_PUBLIC_RPC_URL", sbx.url);
    vi.resetModules();
    owner = await H.createAccount(sbx, "owner"); alice = await H.createAccount(sbx, "alice"); bob = await H.createAccount(sbx, "bob");
    tokenId = await H.deployToken(sbx, owner);
    const da = await H.deployMarket(sbx, { name: "mkt-a", tokenId, resolver: owner, cutoffMs: 75_000, question: "Market A: will it rain?" });
    const db = await H.deployMarket(sbx, { name: "mkt-b", tokenId, resolver: owner, cutoffMs: 3_600_000, question: "Market B: will it snow?" });
    A = await mkMarket("m_a", da, "Market A: will it rain?"); B = await mkMarket("m_b", db, "Market B: will it snow?");
    const { NearAdapter } = await import("@/lib/near/adapter");
    NearAdapter.pollMs = 400;
    const markets = new Map([["m_a", A], ["m_b", B]]);
    const { apiMarket, FRESH } = await import("./helpers");
    const api = {
      market: async (ref: string) => { const m = markets.get(ref)!; return { ...apiMarket(ref, m.contract!, { question: m.question, trading: m.chainClaim!.trading, tradingCutoff: { ns: m.chainClaim!.cutoffNs, iso: null }, token: { symbol: m.token.symbol, name: "n", decimals: 6, isTestToken: true } }), freshness: FRESH }; },
      markets: async () => ({ items: [], page: { limit: 1, offset: 0, total: 0 }, freshness: FRESH }),
    };
    adapter = new NearAdapter(api as never);
    calls = () => sbx.hashes.length;
  }, 120_000);
  afterAll(async () => {
    if (process.env.SANDBOX_REPORT && sbx) writeFileSync(process.env.SANDBOX_REPORT, JSON.stringify({ network: "near-sandbox (local, throwaway)", rootId: sbx.rootId, contracts: { A: A.contract, B: B.contract }, transactions: sbx.hashes }, null, 2));
    await sbx?.stop();
  });

  it("both contracts share the market id and token yet verify independently", async () => {
    expect(A.contract!.marketId).toBe(B.contract!.marketId);
    expect(A.contract!.contractId).not.toBe(B.contract!.contractId);
    expect(A.contract!.tokenId).toBe(B.contract!.tokenId);
    await adapter.verify(A); await adapter.verify(B);
    expect(adapter.deployment(A)).toEqual({ state: "ok" });
    expect(adapter.deployment(B)).toEqual({ state: "ok" });
  }, 60_000);

  it("registration: token once, then each market contract separately", async () => {
    for (const who of [alice, bob]) {
      as(who);
      const before = await acct(who, A);
      expect(before.holdings[0].registered).toBe(false);
      expect(before.wallets[0].tokenRegistered).toBe(false);
      await adapter.registerToken(A, reporter().r);
      const rA = reporter(); await adapter.registerMarket(A, rA.r);
      expect(rA.last()).toMatchObject({ phase: "confirmed" });
      expect((await acct(who, A)).holdings[0].registered).toBe(true);
      expect((await acct(who, B)).holdings[0].registered).toBe(false); // registering with A does not register with B
      await adapter.registerMarket(B, reporter().r);
      expect((await acct(who, B)).holdings[0].registered).toBe(true);
    }
    for (const who of [alice, bob]) await H.call(sbx, owner, tokenId, "mint", { account_id: who.accountId, amount: tok(100).toString() }, 0n, 30n * TG, "mint test tokens (token owner)");
  }, 180_000);

  it("deposits stay in the market they were sent to; the wallet balance is one number per token", async () => {
    as(alice);
    const d1 = reporter(); await adapter.deposit(A, tok(20), d1.r);
    expect(d1.last().message).toMatch(/Deposited 20 /);
    await adapter.deposit(B, tok(5), reporter().r);
    as(bob);
    await adapter.deposit(A, tok(30), reporter().r); await adapter.deposit(B, tok(30), reporter().r);
    const a = await acct(alice, A), b = await acct(alice, B);
    expect(a.holdings[0].available).toBe(tok(20));
    expect(b.holdings[0].available).toBe(tok(5));
    expect(a.wallets[0].balance).toBe(tok(75));
    expect(b.wallets[0].balance).toBe(tok(75)); // the same wallet balance, not 75 + 75 and not split per market
  }, 180_000);

  let offA: Offer, offB: Offer, offA2: Offer;
  it("overlapping local offer ids on the two contracts are different offers", async () => {
    as(bob);
    for (const m of [A, B]) await adapter.split(m, tok(10), reporter().r);
    const mk = (m: Market, price: number, qty: number) => adapter.createOffer(m, { marketId: m.id, outcome: "YES", side: "sell", price: tok(price), qty: tok(qty) }, reporter().r);
    await mk(A, 0.65, 5); await mk(B, 0.7, 5); await mk(A, 0.8, 2);
    const [oa, ob] = [(await acct(bob, A)).offers, (await acct(bob, B)).offers];
    offA = oa.find((o: Offer) => o.price === tok(0.65))!; offA2 = oa.find((o: Offer) => o.price === tok(0.8))!; offB = ob[0];
    expect(offA.offerId).toBe(offB.offerId); // both are offer "1" on their own contract
    expect(offA.id).not.toBe(offB.id); // frontend identities differ
    expect(offA.id).toBe(`m_a:${offA.offerId}`);
    expect(offB.price).toBe(tok(0.7));
  }, 180_000);

  it("a partial fill on A leaves B's identically-numbered offer untouched", async () => {
    as(alice);
    const r = reporter();
    await adapter.fillOffer(A, offA, tok(2), r.r);
    expect(r.last()).toMatchObject({ phase: "confirmed" });
    expect(r.last().message).toBe("Filled 2 shares for 1.3 tNOC (3 still on that offer).");
    const onA = await H.view(sbx, A.contract!.contractId, "get_offer", { offer_id: offA.offerId });
    const onB = await H.view(sbx, B.contract!.contractId, "get_offer", { offer_id: offB.offerId });
    expect(onA.remaining_quantity).toBe(tok(3).toString());
    expect(onB.remaining_quantity).toBe(tok(5).toString());
    expect((await acct(alice, A)).positions[0]).toMatchObject({ outcome: "YES", qty: tok(2) });
    expect((await acct(alice, B)).positions).toHaveLength(0);
    expect((await acct(alice, A)).holdings[0].available).toBe(tok(20) - 1_300_000n);
    expect((await acct(alice, B)).holdings[0].available).toBe(tok(5));
  }, 120_000);

  it("limit offer then cancel on B changes only B", async () => {
    as(alice);
    const aBefore = (await acct(alice, A)).holdings[0];
    const rr = reporter();
    await adapter.createOffer(B, { marketId: B.id, outcome: "YES", side: "buy", price: tok(0.4), qty: tok(4) }, rr.r);
    const mine = (await acct(alice, B)).offers[0];
    expect((await acct(alice, B)).holdings[0]).toMatchObject({ available: tok(5) - tok(1.6), committed: tok(1.6) });
    const c = reporter(); await adapter.cancelOffer(B, mine, c.r);
    expect(c.last().message).toMatch(/Released 1.6 tNOC/);
    expect((await acct(alice, B)).holdings[0]).toMatchObject({ available: tok(5), committed: 0n });
    expect((await acct(alice, A)).holdings[0]).toEqual(aBefore);
  }, 120_000);

  it("an offer that another trader cancelled is refused before the wallet is opened", async () => {
    as(bob);
    await adapter.cancelOffer(A, offA2, reporter().r);
    as(alice);
    const n = calls();
    await expect(adapter.fillOffer(A, offA2, tok(1), reporter().r)).rejects.toThrow(/another trader filled or cancelled it/);
    expect(calls()).toBe(n);
  }, 120_000);

  it("a pending cancel is still possible after the cutoff, trading and splitting are closed, deposits and withdrawals stay open", async () => {
    as(bob);
    await adapter.createOffer(A, { marketId: A.id, outcome: "YES", side: "sell", price: tok(0.9), qty: tok(1) }, reporter().r);
    const resting = (await acct(bob, A)).offers.find((o: Offer) => o.price === tok(0.9))!;
    const cutoff = A.closesAt;
    while (Date.now() < cutoff + 2000) await new Promise((r) => setTimeout(r, 500));
    // the contract, not the clock or the indexer, decides
    const m = (await adapter.getMarket("m_a"))!;
    expect(m).toMatchObject({ status: "awaiting", chain: "fresh", flags: { splitOpen: false, tradingOpen: false, mergeOpen: true } });
    as(alice);
    const n = calls();
    await expect(adapter.fillOffer(A, resting, tok(1), reporter().r)).rejects.toThrow(/Trading is closed/);
    await expect(adapter.createOffer(A, { marketId: A.id, outcome: "YES", side: "buy", price: tok(0.5), qty: tok(1) }, reporter().r)).rejects.toThrow(/Trading is closed/);
    await expect(adapter.split(A, tok(1), reporter().r)).rejects.toThrow(/Creating shares is closed/);
    expect(calls()).toBe(n);
    await adapter.deposit(A, tok(1), reporter().r); // deposits stay open
    as(bob);
    const c = reporter(); await adapter.cancelOffer(A, resting, c.r); // cancellation stays open
    expect(c.last().phase).toBe("confirmed");
    // B is unaffected by A's cutoff
    expect((await adapter.getMarket("m_b"))).toMatchObject({ status: "open", flags: { tradingOpen: true, splitOpen: true } });
  }, 240_000);

  it("resolution preview, then Redeem credits internal collateral only, then Withdraw moves tokens separately", async () => {
    await H.call(sbx, owner, A.contract!.contractId, "resolve_market", { market_id: A.contract!.marketId, outcome: "Yes", evidence: "Sandbox evidence" }, 1n, 100n * TG, "resolve_market (resolver)");
    as(alice);
    const resolved = (await adapter.getMarket("m_a"))!;
    expect(resolved).toMatchObject({ status: "resolved", flags: { mergeOpen: false } });
    expect(resolved.resolution.outcome).toBe("YES");
    const p = (await adapter.redeemPreview(A, alice.accountId))!;
    expect(p).toMatchObject({ redeemable: true, outcome: "YES", winningShares: tok(2), payout: tok(2) });
    const before = await acct(alice, A);
    const rd = reporter(); await adapter.redeem(A, rd.r);
    expect(rd.last().message).toMatch(/2 tNOC winning payout.*inside this market\. Withdraw it/);
    const mid = await acct(alice, A);
    expect(mid.wallets[0].balance).toBe(before.wallets[0].balance); // redeem moved NO tokens
    expect(mid.holdings[0].available).toBe(before.holdings[0].available + tok(2));
    expect(mid.positions).toHaveLength(0);
    const w = reporter(); await adapter.withdraw(A, mid.holdings[0].available, w.r);
    expect(w.last()).toMatchObject({ phase: "confirmed" });
    const after = await acct(alice, A);
    expect(after.holdings[0].available).toBe(0n);
    expect(after.wallets[0].balance).toBe(mid.wallets[0].balance + mid.holdings[0].available);
    expect(after.holdings[0].withdrawal).toMatchObject({ status: "Completed" });
    // market B's deposit never moved
    expect((await acct(alice, B)).holdings[0].available).toBe(tok(5));
    expect((await adapter.getMarket("m_b"))!.status).toBe("open");
  }, 240_000);
});
